#!/usr/bin/env bash
# e2e suite: the generated one-command bootstraps (v1.7.0). bootstrap/ubuntu.sh and bootstrap/macos.sh
# are built from bootstrap/src/ by scripts/build-bootstrap.mjs and committed, because `curl … | bash`
# fetches ONE file and cannot source a shared sibling. Fails when a committed output is stale, or when
# the macOS one uses syntax the stock bash 3.2 lacks (the runtime check is 72-bootstrap-macos on a Mac).
# Sourced by scripts/ci-e2e.sh.

OUT_BB="$(node "$REPO_ROOT/scripts/build-bootstrap.mjs" --check 2>&1; echo "exit=$?")"
chk "bootstrap build: committed scripts match bootstrap/src" 'echo "$OUT_BB" | grep -q "exit=0"'
chk "bootstrap build: outputs say they are generated" 'grep -q "GENERATED by scripts/build-bootstrap.mjs" "$REPO_ROOT/bootstrap/ubuntu.sh" && grep -q "GENERATED by scripts/build-bootstrap.mjs" "$REPO_ROOT/bootstrap/macos.sh"'
chk "bootstrap build: no include line left in an output" '[ -f "$REPO_ROOT/bootstrap/macos.sh" ] && ! grep -qE "# @include common\.sh[[:space:]]*$" "$REPO_ROOT/bootstrap/ubuntu.sh" "$REPO_ROOT/bootstrap/macos.sh"'
# Comments stripped first: the sources name these constructs in prose to forbid them.
BASH4_ONLY='mapfile|readarray|coproc|declare -[a-zA-Z]*[An]|local -[a-zA-Z]*[An]|[a-zA-Z_],,[}]|[a-zA-Z_]\^\^[}]|\|&|&>>|;;&'
chk "bootstrap build: macos.sh avoids bash-4-only syntax" '[ -f "$REPO_ROOT/bootstrap/macos.sh" ] && ! sed -e "/^[[:space:]]*#/d" -e "s/[[:space:]]#.*$//" "$REPO_ROOT/bootstrap/macos.sh" | grep -nE "$BASH4_ONLY"'
